// FIXED template (deterministic, no AI, no drift). Booking-triggered upsell.
// Bullets MUST match the admin app's locked premium cards.
let e = $('Get Engagement').item.json;
if (Array.isArray(e)) e = e[0];
e = e || {};

const who = (e.owner_first_name && e.owner_first_name.trim()) ? e.owner_first_name.trim() : '';
const biz = e.business_name || 'your salon';
const hasDetail = e.latest_customer_first_name && e.latest_service_name;

const bookingLine = hasDetail
  ? biz + ' just took a booking off the free page \u2014 ' + e.latest_customer_first_name + ' for ' + e.latest_service_name + (e.latest_booking_date_human ? ' on ' + e.latest_booking_date_human : '') + '. That\'s the whole idea.'
  : biz + ' just took a booking straight off the free page I set up. That\'s the whole idea.';

const text = [
  (who ? who + ', quick one.' : 'Quick one.'),
  '',
  bookingLine,
  '',
  'Now imagine the full setup:',
  '- Take deposits so clients can\'t no-show',
  '- Automatic WhatsApp + email reminders before every appointment',
  '- Your own domain instead of the shared link',
  '- An online store for products, vouchers and packages',
  '- Your branding only \u2014 the "Powered by Streamline" comes off',
  '',
  'From R2,500 depending on what you want \u2014 or the full setup (proper website, online store, bookings, payments, all the automation wired in) from around R15-20k, live in about a week.',
  '',
  'I\'ve got 2 spots open next week \u2014 want a quick 15-min chat to map it out?',
  '',
  '\u2014 Christiaan from Streamline'
].join('\n');

return [{ json: { prospect_id: e.prospect_id, business_name: biz, draft_text: text } }];

